/**
 * solarpunkid.eth as ENS's Universal Resolver answered for it on 2026-10-29, after the name moved
 * to ENSv2. The calls and the answer were encoded independently with viem 2.55.
 */
export const SOLARPUNKID = {
  name: 'solarpunkid.eth',
  dnsEncoded: '0b736f6c617270756e6b69640365746800',
  contenthashCall: 'bc1c58d18434204f752f86aa77edfea2f3e47273534f3f0c0e8810046350d0b99b76961a',
  resolveCall:
    '',
  contenthash: 'e40101fa011b204653174da7be0e18831246396fef76c876fb06b0540a07727ebafd6976f953bf',
  resolver: '0x7f3cfc22b509e1b7d88f7234c007846adc68089d',
  resolveAnswer:
    '',
}

function word(value: number): string {
  return value.toString(16).padStart(64, '0')
}

function abiBytes(hex: string): string {
  const length = hex.length / 2
  return word(length) + hex.padEnd(Math.ceil(length / 32) * 64, '0')
}

/** ABI encoding of the `(bytes answer, address resolver)` that resolve returns, the answer being `(bytes contenthash)`. */
export function encodeResolveAnswer(contenthash: string, resolver = SOLARPUNKID.resolver): string {
  const answer = word(32) + abiBytes(contenthash)
  return '0x' + word(64) + resolver.slice(2).padStart(64, '0') + abiBytes(answer)
}
